#include <gb/gb.h>
#include <gb/cgb.h>
#include <stdbool.h>
#include <stdint.h>
#include <rand.h>

#include "assets.h"

#define NOVA_STATE (*(volatile uint8_t *)0xCF00)

/* ---- tile indices (loaded at 0x80) ---- */
enum {
    T_EMPTY = 0u,
    T_SOLID = 1u,
    T_SPIKE = 2u,
    T_GOAL = 3u,
    T_PLAT = 4u,
    T_POST = 5u,
    T_BALL = 6u,
    T_PLAYER = 7u,
    T_COUNT = 8u
};

enum {
    SPR_PLAYER = 0u,
    SPR_BALL = 1u,
    MAX_LIVES = 5u,
    NUM_ROOMS = 3u,
    /* pixel sizes */
    PW = 8,
    PH = 8,
    BW = 6,
    BH = 6,
    /* physics (fixed-ish: position in pixels, velocity in 1/2 px units stored as int8) */
    GRAVITY = 1,
    MAX_FALL = 6,
    MOVE_SPEED = 2,
    JUMP_V = -6,
    WALL_JUMP_V = -5,
    WALL_JUMP_X = 3,
    THROW_SPEED = 4,
    BALL_GRAV = 1,
    BALL_MAX_FALL = 5
};

