/*
 * APU helpers. Reusable one-call sound effects on the Game Boy's channels.
 */
static void sound_init(void) {
    NR52_REG = 0x80u;
    NR51_REG = 0xFFu;
    NR50_REG = 0x77u;
}

static void sfx_beep(void) {
    NR10_REG = 0x00u;
    NR11_REG = 0x80u;
    NR12_REG = 0xF1u;
    NR13_REG = 0x83u;
    NR14_REG = 0x87u;
}

static void sfx_boom(void) {
    NR41_REG = 0x00u;
    NR42_REG = 0xF3u;
    NR43_REG = 0x54u;
    NR44_REG = 0x80u;
}

static void sfx_jingle(void) {
    static const uint16_t notes[4] = {1797u, 1849u, 1881u, 1923u};
    uint8_t i;
    uint8_t frame;

    for (i = 0u; i < 4u; ++i) {
        NR21_REG = 0x80u;
        NR22_REG = 0xF2u;
        NR23_REG = (uint8_t)notes[i];
        NR24_REG = (uint8_t)(0x80u | (notes[i] >> 8));
        for (frame = 0u; frame < 8u; ++frame) {
            wait_vbl_done();
        }
    }
}

static void sfx_jump(void) {
    NR10_REG = 0x15u;
    NR11_REG = 0x80u;
    NR12_REG = 0xF2u;
    NR13_REG = 0xD0u;
    NR14_REG = 0x86u;
}

static void sfx_throw(void) {
    NR10_REG = 0x00u;
    NR11_REG = 0x40u;
    NR12_REG = 0xD1u;
    NR13_REG = 0x20u;
    NR14_REG = 0x87u;
}

static uint8_t tile_at(int16_t x, int16_t y) {
    int16_t tx, ty;

    /* Convert OAM coords to background pixel then tile */
    tx = (x - 8) >> 3;
    ty = (y - 16) >> 3;
    if (tx < 0 || ty < 0 || tx >= 20 || ty >= 18) {
        return T_SOLID;
    }
    return cmap[(uint8_t)ty * 20u + (uint8_t)tx];
}

static bool solid_tile(uint8_t t) {
    return t == T_SOLID || t == T_PLAT || t == T_POST;
}

static bool hazard_tile(uint8_t t) {
    return t == T_SPIKE;
}

static bool goal_tile(uint8_t t) {
    return t == T_GOAL;
}

/* Sample body corners for player (6x7 hitbox inside 8x8) */
static uint8_t collide_solid_box(int16_t x, int16_t y, uint8_t w, uint8_t h) {
    if (solid_tile(tile_at(x, y))) return 1u;
    if (solid_tile(tile_at((int16_t)(x + w - 1), y))) return 1u;
    if (solid_tile(tile_at(x, (int16_t)(y + h - 1)))) return 1u;
    if (solid_tile(tile_at((int16_t)(x + w - 1), (int16_t)(y + h - 1)))) return 1u;
    /* mid samples for thin platforms */
    if (solid_tile(tile_at((int16_t)(x + (w >> 1)), y))) return 1u;
    if (solid_tile(tile_at((int16_t)(x + (w >> 1)), (int16_t)(y + h - 1)))) return 1u;
    return 0u;
}

static uint8_t touch_hazard(int16_t x, int16_t y, uint8_t w, uint8_t h) {
    if (hazard_tile(tile_at(x, y))) return 1u;
    if (hazard_tile(tile_at((int16_t)(x + w - 1), y))) return 1u;
    if (hazard_tile(tile_at(x, (int16_t)(y + h - 1)))) return 1u;
    if (hazard_tile(tile_at((int16_t)(x + w - 1), (int16_t)(y + h - 1)))) return 1u;
    return 0u;
}

static uint8_t touch_goal(int16_t x, int16_t y, uint8_t w, uint8_t h) {
    if (goal_tile(tile_at(x, y))) return 1u;
    if (goal_tile(tile_at((int16_t)(x + w - 1), y))) return 1u;
    if (goal_tile(tile_at(x, (int16_t)(y + h - 1)))) return 1u;
    if (goal_tile(tile_at((int16_t)(x + w - 1), (int16_t)(y + h - 1)))) return 1u;
    return 0u;
}

static void draw_room(void) {
    uint8_t i;
    uint8_t buf[20 * 18];

    for (i = 0u; i < 20u * 18u; ++i) {
        cmap[i] = room_maps[room][i];
        buf[i] = (uint8_t)(0x80u + cmap[i]);
    }
    set_bkg_tiles(0u, 0u, 20u, 18u, buf);
}

static void place_ball_spawn(void) {
    /* Seed-based offset so ball X varies run to run within a small range */
    uint8_t ox = (uint8_t)(rand() & 3u);
    uint8_t tx = room_ball_tx[room];
    uint8_t ty = room_ball_ty[room];

    if (tx + ox < 18u) {
        tx = (uint8_t)(tx + ox);
    }
    bx = (int16_t)(tx * 8 + 8);
    by = (int16_t)(ty * 8 + 16);
    bvx = 0;
    bvy = 0;
    ball_alive = 1u;
    ball_held = 0u;
    holding_ball = 0u;
}

static void spawn_player(void) {
    px = (int16_t)(room_spawn_tx[room] * 8 + 8);
    py = (int16_t)(room_spawn_ty[room] * 8 + 16);
    pvx = 0;
    pvy = 0;
    facing = 1;
    on_ground = 0u;
    on_wall = 0u;
    jump_held = 0u;
    down_held = 0u;
}

static void load_room(void) {
    draw_room();
    spawn_player();
    place_ball_spawn();
    move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
    move_sprite(SPR_BALL, (uint8_t)bx, (uint8_t)by);
}

static void ensure_seed(void) {
    uint16_t s;
    if (seeded) {
        return;
    }
    seeded = 1u;
    s = (uint16_t)DIV_REG;
    s |= (uint16_t)(DIV_REG << 8);
    if (s == 0u) {
        s = 1u;
    }
    initrand(s);
    rng_pool = (uint8_t)rand();
    /* Re-roll ball offset now that RNG is live */
    place_ball_spawn();
}

static void try_move_player(int8_t dx, int8_t dy) {
    int16_t nx = px;
    int16_t ny = py;

    if (dx != 0) {
        nx = (int16_t)(px + dx);
        if (!collide_solid_box(nx, py, PW - 2, PH - 1)) {
            px = nx;
        } else {
            /* snap against wall */
            if (dx > 0) {
                while (!collide_solid_box((int16_t)(px + 1), py, PW - 2, PH - 1)) {
                    px++;
                }
                on_wall = 2u;
            } else {
                while (!collide_solid_box((int16_t)(px - 1), py, PW - 2, PH - 1)) {
                    px--;
                }
                on_wall = 1u;
            }
            pvx = 0;
        }
    }
    if (dy != 0) {
        ny = (int16_t)(py + dy);
        if (!collide_solid_box(px, ny, PW - 2, PH - 1)) {
            py = ny;
            if (dy > 0) {
                on_ground = 0u;
            }
        } else {
            if (dy > 0) {
                while (!collide_solid_box(px, (int16_t)(py + 1), PW - 2, PH - 1)) {
                    py++;
                }
                on_ground = 1u;
                pvy = 0;
            } else {
                while (!collide_solid_box(px, (int16_t)(py - 1), PW - 2, PH - 1)) {
                    py--;
                }
                pvy = 0;
            }
        }
    }
}

static void update_ground_wall(void) {
    on_ground = collide_solid_box(px, (int16_t)(py + 1), PW - 2, PH - 1) ? 1u : 0u;
    on_wall = 0u;
    if (!on_ground) {
        if (collide_solid_box((int16_t)(px - 1), py, PW - 2, PH - 1)) {
            on_wall = 1u;
        } else if (collide_solid_box((int16_t)(px + 1), py, PW - 2, PH - 1)) {
            on_wall = 2u;
        }
    }
}

static void kill_player(void) {
    sfx_boom();
    if (lives > 0u) {
        --lives;
    }
    if (lives == 0u) {
        lost = 1u;
        return;
    }
    /* Instant restart of current room */
    spawn_player();
    place_ball_spawn();
}

static void try_move_ball(void) {
    int16_t nx, ny;
    uint8_t i;

    if (!ball_alive || ball_held) {
        return;
    }

    /* horizontal */
    if (bvx != 0) {
        nx = (int16_t)(bx + bvx);
        if (!collide_solid_box(nx, by, BW, BH)) {
            bx = nx;
        } else {
            /* bounce damp */
            bvx = (int8_t)(-bvx / 2);
            if (bvx == 0) {
                /* settle */
            }
        }
    }
    /* gravity */
    bvy = (int8_t)(bvy + BALL_GRAV);
    if (bvy > BALL_MAX_FALL) {
        bvy = BALL_MAX_FALL;
    }
    if (bvy != 0) {
        ny = (int16_t)(by + bvy);
        if (!collide_solid_box(bx, ny, BW, BH)) {
            by = ny;
        } else {
            if (bvy > 0) {
                for (i = 0u; i < 8u; ++i) {
                    if (!collide_solid_box(bx, (int16_t)(by + 1), BW, BH)) {
                        by++;
                    } else {
                        break;
                    }
                }
            }
            bvy = (int8_t)(-bvy / 2);
            if (bvy > -1 && bvy < 2) {
                bvy = 0;
                bvx = (int8_t)(bvx / 2);
            }
        }
    }

    /* Ball falls out of room */
    if (by > 160) {
        place_ball_spawn();
    }
    /* Ball can clear spikes by covering? unused — ball hits goal posts no-op */
}

static bool overlaps_ball(void) {
    int16_t dx, dy;
    if (!ball_alive || ball_held) {
        return false;
    }
    dx = px - bx;
    dy = py - by;
    if (dx < 0) dx = (int16_t)-dx;
    if (dy < 0) dy = (int16_t)-dy;
    return (dx < 10 && dy < 10);
}

static void pick_up_ball(void) {
    ball_held = 1u;
    holding_ball = 1u;
    ball_alive = 1u;
    bvx = 0;
    bvy = 0;
    sfx_beep();
}

static void throw_ball(void) {
    ball_held = 0u;
    holding_ball = 0u;
    ball_alive = 1u;
    bx = (int16_t)(px + (facing > 0 ? 8 : -6));
    by = py;
    bvx = (int8_t)(facing * THROW_SPEED);
    bvy = -2;
    sfx_throw();
}

static void update_player(uint8_t keys) {
    int8_t dx = 0;

    if ((keys & J_LEFT) != 0u) {
        dx = (int8_t)-MOVE_SPEED;
        facing = -1;
    } else if ((keys & J_RIGHT) != 0u) {
        dx = MOVE_SPEED;
        facing = 1;
    }

    /* horizontal */
    if (dx != 0) {
        try_move_player(dx, 0);
    }

    update_ground_wall();

    /* jump / wall-jump on A edge */
    if ((keys & J_A) != 0u) {
        if (!jump_held) {
            jump_held = 1u;
            if (on_ground) {
                pvy = JUMP_V;
                on_ground = 0u;
                sfx_jump();
            } else if (on_wall == 1u) {
                pvy = WALL_JUMP_V;
                pvx = WALL_JUMP_X;
                facing = 1;
                sfx_jump();
            } else if (on_wall == 2u) {
                pvy = WALL_JUMP_V;
                pvx = (int8_t)-WALL_JUMP_X;
                facing = -1;
                sfx_jump();
            }
        }
    } else {
        jump_held = 0u;
        /* variable jump cut */
        if (pvy < -2) {
            pvy = (int8_t)(pvy + 1);
        }
    }

    /* wall slide */
    if (!on_ground && on_wall != 0u && pvy > 1) {
        pvy = 1;
    }

    /* apply stored wall-jump x momentum briefly */
    if (pvx != 0) {
        try_move_player(pvx, 0);
        if (pvx > 0) {
            pvx--;
        } else if (pvx < 0) {
            pvx++;
        }
    }

    /* gravity */
    if (!on_ground) {
        pvy = (int8_t)(pvy + GRAVITY);
        if (pvy > MAX_FALL) {
            pvy = MAX_FALL;
        }
    } else if (pvy > 0) {
        pvy = 0;
    }

    if (pvy != 0) {
        try_move_player(0, pvy);
    }

    update_ground_wall();

    /* pick up / throw with Down edge */
    if ((keys & J_DOWN) != 0u) {
        if (!down_held) {
            down_held = 1u;
            if (holding_ball) {
                throw_ball();
            } else if (overlaps_ball()) {
                pick_up_ball();
            }
        }
    } else {
        down_held = 0u;
    }

    if (holding_ball) {
        bx = (int16_t)(px + (facing > 0 ? 6 : -4));
        by = (int16_t)(py - 2);
    }

    /* hazards / fall death */
    if (touch_hazard(px, py, PW - 2, PH - 1) || py > 160) {
        kill_player();
        return;
    }

    /* goal in final room */
    if (room == (NUM_ROOMS - 1u) && touch_goal(px, py, PW - 2, PH - 1)) {
        won = 1u;
        return;
    }

    /* room exit via right edge (rooms 0 and 1) */
    if (room < (NUM_ROOMS - 1u) && px >= 152) {
        room++;
        sfx_beep();
        load_room();
        return;
    }
    /* left edge soft clamp */
    if (px < 8) {
        px = 8;
    }
}

static void initialize_video(void) {
    DISPLAY_OFF;

    SCX_REG = 0u;
    SCY_REG = 0u;
    WY_REG = 0u;
    WX_REG = 7u;
    STAT_REG = 0u;

    BGP_REG = 0xE4u;
    OBP0_REG = 0xE4u;
    OBP1_REG = 0x1Bu;
    NR52_REG = 0u;

    LCDC_REG = 0x40u;

    /* Still load stock tiles so assets.o links; our tiles overwrite VRAM */
    set_bkg_data(0x80u, BREAKOUT_TILE_COUNT, breakout_tile_data);
    set_bkg_data(0x80u, T_COUNT, tile_data);

    if (_cpu == CGB_TYPE) {
        set_bkg_palette(0, 1, red_bgp);
        set_sprite_palette(0, 1, spr_obp);
    }

    set_sprite_tile(SPR_PLAYER, (uint8_t)(0x80u + T_PLAYER));
    set_sprite_tile(SPR_BALL, (uint8_t)(0x80u + T_BALL));
    set_sprite_prop(SPR_PLAYER, 0u);
    set_sprite_prop(SPR_BALL, 0u);

    SPRITES_8x8;
    SHOW_BKG;
    SHOW_SPRITES;
    DISPLAY_ON;
}

static void initialize_game(void) {
    room = 0u;
    lives = MAX_LIVES;
    won = 0u;
    lost = 0u;
    seeded = 0u;
    rng_pool = 0u;
    load_room();
}

void main(void) {
    uint8_t keys;

    wait_vbl_done();

    initialize_video();
    sound_init();
    initialize_game();
    NOVA_STATE = 1u;

    while (!won && !lost) {
        keys = joypad();

        if (!seeded && keys != 0u) {
            ensure_seed();
        }

        update_player(keys);
        if (won || lost) {
            break;
        }
        try_move_ball();

        move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
        if (ball_alive) {
            move_sprite(SPR_BALL, (uint8_t)bx, (uint8_t)by);
        } else {
            move_sprite(SPR_BALL, 0u, 0u);
        }

        wait_vbl_done();
    }

    NOVA_STATE = won ? 2u : 3u;
    if (won) {
        sfx_jingle();
    } else {
        sfx_boom();
    }
    while (true) {
        wait_vbl_done();
    }
}

details.old_string:
#include <gb/gb.h>
#include <stdbool.h>
#include <stdint.h>

#include "assets.h"

enum {
    TILE_EMPTY = 0x80u,
    TILE_BRICK_LEFT = 0x88u,
    TILE_BRICK_RIGHT = 0x89u,
    TILE_PADDLE_LEFT = 0x8Cu,
    TILE_PADDLE_MIDDLE = 0x8Du,
    TILE_PADDLE_RIGHT = 0x8Eu,
    TILE_BALL = 0x8Fu,

    BALL_SPRITE = 0u,
    PADDLE_LEFT_SPRITE = 1u,
    PADDLE_MIDDLE_SPRITE = 2u,
    PADDLE_RIGHT_SPRITE = 3u,

    PADDLE_Y = 0x98u,
    PADDLE_MIN_X = 0x08u,
    PADDLE_MAX_X = 0x90u,
    PADDLE_INITIAL_X = 0x4Cu,
    BALL_INITIAL_X = 0x32u,
    BALL_INITIAL_Y = 0x78u,
    BALL_LOSS_Y = 0x9Au,
    INITIAL_BRICK_COUNT = 39u
};

/*
 * Nova arcade protocol: one byte at a fixed WRAM address the arcade polls to
 * detect run state. The linker can't move it because it's an absolute pointer,
 * not a variable. 1 = run started, 2 = won, 3 = lost. Every game the pipeline
 * ships MUST keep these three writes intact.
 */
#define NOVA_STATE (*(volatile uint8_t *)0xCF00)

/*
 * These six values correspond to the original ROM's globals at $C0A0-$C0A5.
 * Positions use Game Boy OAM coordinates: visible X is X - 8 and visible Y
 * is Y - 16.
 */
static uint8_t paddle_x;
static uint8_t ball_x;
static uint8_t ball_y;
static int8_t ball_vx;
static int8_t ball_vy;
static uint8_t bricks_remaining;

/*
 * APU helpers. Reusable one-call sound effects on the Game Boy's channels.
 * Remixes should call these (retuning register values if a different pitch
 * or feel is wanted) instead of writing raw NRxx sequences at every new
 * sound moment. sound_init() must run once, after initialize_video(), which
 * powers the APU down like the original ROM did.
 */
static void sound_init(void) {
    NR52_REG = 0x80u; /* APU on; must be set before any other register */
    NR51_REG = 0xFFu; /* every channel to both output terminals */
    NR50_REG = 0x77u; /* max master volume, VIN off */
}

/* Short square blip on channel 1: paddle and brick hits. Non-blocking. */
static void sfx_beep(void) {
    NR10_REG = 0x00u; /* no sweep */
    NR11_REG = 0x80u; /* 50% duty */
    NR12_REG = 0xF1u; /* full volume, fast envelope decay */
    NR13_REG = 0x83u;
    NR14_REG = 0x87u; /* trigger, period 0x783 (~1050 Hz) */
}

/* Noise burst on channel 4: the loss thud. Non-blocking. */
static void sfx_boom(void) {
    NR41_REG = 0x00u;
    NR42_REG = 0xF3u; /* full volume, medium envelope decay */
    NR43_REG = 0x54u; /* mid-pitch noise */
    NR44_REG = 0x80u; /* trigger */
}

/* Rising four-note win arpeggio on channel 2. Blocks about half a second. */
static void sfx_jingle(void) {
    static const uint16_t notes[4] = {1797u, 1849u, 1881u, 1923u}; /* C5 E5 G5 C6 */
    uint8_t i;
    uint8_t frame;

    for (i = 0u; i < 4u; ++i) {
        NR21_REG = 0x80u; /* 50% duty */
        NR22_REG = 0xF2u; /* full volume, gentle decay */
        NR23_REG = (uint8_t)notes[i];
        NR24_REG = (uint8_t)(0x80u | (notes[i] >> 8)); /* trigger */
        for (frame = 0u; frame < 8u; ++frame) {
            wait_vbl_done();
        }
    }
}

static void draw_paddle(void) {
    move_sprite(PADDLE_LEFT_SPRITE, paddle_x, PADDLE_Y);
    move_sprite(PADDLE_MIDDLE_SPRITE, (uint8_t)(paddle_x + 8u), PADDLE_Y);
    move_sprite(PADDLE_RIGHT_SPRITE, (uint8_t)(paddle_x + 16u), PADDLE_Y);
}

static void move_paddle(int8_t delta) {
    int16_t next_x;

    if (delta == 0) {
        paddle_x = PADDLE_INITIAL_X;
    } else {
        next_x = (int16_t)paddle_x + delta;

        if (next_x < PADDLE_MIN_X) {
            next_x = PADDLE_MIN_X;
        } else if (next_x > PADDLE_MAX_X) {
            next_x = PADDLE_MAX_X;
        }

        paddle_x = (uint8_t)next_x;
    }

    draw_paddle();
}

static void remove_brick(uint8_t tile_x, uint8_t tile_y) {
    set_bkg_tile_xy(tile_x, tile_y, TILE_EMPTY);
    set_bkg_tile_xy((uint8_t)(tile_x + 1u), tile_y, TILE_EMPTY);
    --bricks_remaining;
    sfx_beep();
}

static bool overlaps_paddle(uint8_t candidate_x, uint8_t candidate_y) {
    int16_t ball_left;
    int16_t ball_right;
    int16_t paddle_left;
    int16_t paddle_right;

    if ((uint16_t)candidate_y + 5u < PADDLE_Y) {
        return false;
    }

    ball_left = candidate_x;
    ball_right = ball_left + 5;
    paddle_left = paddle_x;
    paddle_right = paddle_left + 24;

    /*
     * This intentionally preserves the ROM's slightly asymmetric right edge:
     * the ball's left sample is inclusive, while its right sample is strict.
     */
    return ((ball_left >= paddle_left) && (ball_left <= paddle_right)) ||
           ((ball_right >= paddle_left) && (ball_right < paddle_right));
}

static bool collides(int8_t delta_x, int8_t delta_y) {
    uint8_t candidate_x;
    uint8_t candidate_y;
    int16_t sample_x;
    int16_t sample_y;
    uint8_t tile_x;
    uint8_t tile_y;
    uint8_t tile;

    candidate_x = (uint8_t)(ball_x + delta_x);
    candidate_y = (uint8_t)(ball_y + delta_y);

    if (overlaps_paddle(candidate_x, candidate_y)) {
        sfx_beep();
        return true;
    }

    /*
     * The original uses a six-pixel collision span and chooses the leading
     * edge from the current global velocity. The X velocity may already have
     * been reversed by the horizontal probe earlier in this frame.
     */
    sample_x = candidate_x;
    sample_y = candidate_y;

    if (ball_vx > 0) {
        sample_x += 5;
    }
    if (ball_vy > 0) {
        sample_y += 5;
    }

    tile_x = (uint8_t)((sample_x - 8) >> 3);
    tile_y = (uint8_t)((sample_y - 16) >> 3);
    tile = get_bkg_tile_xy(tile_x, tile_y);

    if (tile == TILE_BRICK_LEFT) {
        remove_brick(tile_x, tile_y);
    } else if (tile == TILE_BRICK_RIGHT) {
        remove_brick((uint8_t)(tile_x - 1u), tile_y);
    }

    return tile != TILE_EMPTY;
}

static void initialize_video(void) {
    DISPLAY_OFF;

    SCX_REG = 0u;
    SCY_REG = 0u;
    WY_REG = 0u;
    WX_REG = 7u;
    STAT_REG = 0u;

    BGP_REG = 0xE4u;
    OBP0_REG = 0xE4u;
    OBP1_REG = 0x1Bu;
    NR52_REG = 0u;

    /*
     * Bit 4 remains clear so background tile IDs $80-$FF use the signed
     * $8800 tile-data region. SHOW_BKG, SHOW_SPRITES, and DISPLAY_ON below
     * turn this into the original final LCDC value, $C3.
     */
    LCDC_REG = 0x40u;

    set_bkg_data(0x80u, BREAKOUT_TILE_COUNT, breakout_tile_data);
    set_bkg_tiles(
        0u,
        0u,
        BREAKOUT_MAP_WIDTH,
        BREAKOUT_MAP_HEIGHT,
        breakout_background_map
    );

    set_sprite_tile(BALL_SPRITE, TILE_BALL);
    set_sprite_tile(PADDLE_LEFT_SPRITE, TILE_PADDLE_LEFT);
    set_sprite_tile(PADDLE_MIDDLE_SPRITE, TILE_PADDLE_MIDDLE);
    set_sprite_tile(PADDLE_RIGHT_SPRITE, TILE_PADDLE_RIGHT);

    SPRITES_8x8;
    SHOW_BKG;
    SHOW_SPRITES;
    DISPLAY_ON;
}

static void initialize_game(void) {
    paddle_x = PADDLE_INITIAL_X;
    ball_x = BALL_INITIAL_X;
    ball_y = BALL_INITIAL_Y;
    ball_vx = 1;
    ball_vy = -1;
    bricks_remaining = INITIAL_BRICK_COUNT;

    move_paddle(0);
    move_sprite(BALL_SPRITE, ball_x, ball_y);
}

void main(void) {
    uint8_t keys;

    /*
     * The recovered CRT clears a larger runtime area than modern GBDK does.
     * Waiting one VBlank here aligns the first active gameplay frame with the
     * original ROM (frame 90 after reset in the deterministic SameBoy boot).
     */
    wait_vbl_done();

    initialize_video();
    sound_init();
    initialize_game();
    NOVA_STATE = 1u;

    while (bricks_remaining != 0u) {
        keys = joypad();

        if ((keys & J_LEFT) != 0u) {
            move_paddle(-2);
        } else if ((keys & J_RIGHT) != 0u) {
            move_paddle(2);
        }

        if (ball_y >= BALL_LOSS_Y) {
            break;
        }

        if (collides(ball_vx, 0)) {
            ball_vx = (int8_t)-ball_vx;
        }

        if (collides(0, ball_vy)) {
            ball_vy = (int8_t)-ball_vy;
        }

        ball_x = (uint8_t)(ball_x + ball_vx);
        ball_y = (uint8_t)(ball_y + ball_vy);
        move_sprite(BALL_SPRITE, ball_x, ball_y);
        wait_vbl_done();
    }

    /* The original silently idles forever after both a win and a loss. */
    NOVA_STATE = bricks_remaining == 0u ? 2u : 3u;
    if (bricks_remaining == 0u) {
        sfx_jingle();
    } else {
        sfx_boom();
    }
    while (true) {
        wait_vbl_done();
    }
}

