// TITLE: Postie
// DESC: A three-room wall-jumping platformer with throwable balls and instant restarts
// CONTROLS: d-pad to move, A to jump, B to throw ball

#include <gb/gb.

rawInput.old_string:
static void draw_room(void) {
    uint8_t i;
