    initialize_game();
    NOVA_STATE = 1;

    while (!won && !lost) {
        keys = joypad();

        if (!seeded && keys != 0u) {
            ensure_seed();
        }

        update_player(keys);
        if (won || lost) {
            break;
        }
        try_move_ball();

        move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
        if (ball_alive) {
            move_sprite(SPR_BALL, (uint8_t)bx, (uint8_t)by);
        } else {
            move_sprite(SPR_BALL, 0u, 0u);
        }

        wait_vbl_done();
    }

    if (won) {
        NOVA_STATE = 2;
        sfx_jingle();
    } else {
        NOVA_STATE = 3;
        sfx_boom();
    }
    while (true) {
        wait_vbl_done();
    }
}

